    "1-exp(-kt)":lambda k,t: 1-np.exp(-k*t),
    "t exp(-kt)":lambda k,t: t*np.exp(-k*t),
    "sqrt(t)exp(-kt)":lambda k,t: np.sqrt(t)*np.exp(-k*t),
